{
  "title": "HCV Treatment Adherence Game",
  "perWatchSecond": 5,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Adherence Threshold",
      "goal": "Observe how increasing treatment adherence affects the spread of HCV.",
      "control": {
        "parameter": "theta",
        "label": "Adherence Proportion",
        "lowEnd": "0.30",
        "highEnd": "0.80"
      },
      "watch": "r",
      "whatIf": {
        "prompt": "What if adherence rises to 70%?",
        "parameter": "theta",
        "value": 0.7
      },
      "difference": {
        "compartment": "r",
        "summary": "at",
        "at": 20,
        "time": 20,
        "relation": "higher",
        "by": 0.01
      },
      "effect": "At 20 years, recovered individuals are at least 1% more when adherence is 70% compared to 50%.",
      "prediction": {
        "prompt": "Will higher adherence increase recoveries?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Headline Result",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Keep adherence at 70% for next level."
    },
    {
      "kind": "idea",
      "finding": 3,
      "title": "Combined Adherence and Acute Recovery",
      "goal": "See the joint effect of better adherence and faster acute recovery on transmission.",
      "control": {
        "parameter": "eta",
        "label": "Acute Recovery Proportion",
        "lowEnd": "0.10",
        "highEnd": "0.50"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if acute recovery rises to 40% while adherence stays at 70%?",
        "parameter": "eta",
        "value": 0.4
      },
      "difference": {
        "compartment": "cq",
        "summary": "at",
        "at": 20,
        "time": 20,
        "relation": "lower",
        "by": 0.003
      },
      "effect": "At 20 years, chronically infected who quit treatment are at least 0.003 fewer when acute recovery is 40% compared to 30%.",
      "prediction": {
        "prompt": "Will faster acute recovery reduce quitters?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Synergistic Impact",
        "quote": "Our model unraveled the synergistic impact of simultaneously enhancing the recovery rate of acutely infected individuals and treatment adherence on reducing $ℛ_{0}$."
      },
      "carryForward": "Maintain adherence at 70% and acute recovery at 40%."
    },
    {
      "kind": "result",
      "finding": 6,
      "title": "Chronic Recovery Rate Effect",
      "goal": "Test how increasing chronic recovery pushes the reproduction number below the epidemic threshold.",
      "control": {
        "parameter": "rho",
        "label": "Chronic Recovery Rate",
        "lowEnd": "0.03",
        "highEnd": "0.25"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if chronic recovery rises to 0.19 while adherence is 70% and acute recovery is 40%?",
        "parameter": "rho",
        "value": 0.19
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 20,
        "time": 20,
        "relation": "lower",
        "by": 0.002
      },
      "effect": "At 20 years, acutely infected individuals are at least 0.002 fewer when chronic recovery is 0.19 compared to 0.053.",
      "prediction": {
        "prompt": "Will higher chronic recovery reduce acute infections?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Chronic Recovery Impact",
        "quote": "When ρ approaches a value of approximately 0.19, we observe that $ℛ_{0}$ falls below 1."
      },
      "carryForward": null
    }
  ],
  "limits": [
    "All changes must keep parameters within realistic biological ranges.",
    "Time per level must display within 20 seconds at 4× speed.",
    "Differences must be visible as at least 3 figures in a town of 120."
  ]
}
